Think: Resolve paths and symlinks from the raw listing, log unresolved links, keep only normalized regular files, deduplicate and save to temp_var_inventory/file_list.txt.

Act: bash

```bash
awk -F'\t' '{
 path=$2; gsub(/"/, "\\\"", path);
 if($1=="f"||$1=="l"){
   cmd="readlink -f \"" path "\" 2>/dev/null";
   target="";
   if((cmd | getline target) > 0){ close(cmd);
     if(target!=""){
       cmd2="stat -c %F \"" target "\" 2>/dev/null";
       type="";
       if((cmd2 | getline type) > 0){ close(cmd2);
         if(type=="regular file") print target;
       }
     } else { print "UNRESOLVED: " path > "temp_var_inventory/errors.log" }
   } else { close(cmd); print "UNRESOLVED: " path > "temp_var_inventory/errors.log" }
 }
}' temp_var_inventory/raw_listing.txt | sort -u > temp_var_inventory/file_list.txt
```

