Think: Extract and normalize CPU count candidates from the aggregated raw data and write cleaned candidates, reconciliation notes, and a marked primary candidate into temp_cpu_check/cpu_count_candidates.txt.

Act: bash

```bash
awk 'BEGIN{src=""}
/^== lscpu ==/ {src="lscpu"; next}
/^== / {src=""; next}
src=="lscpu" && /CPU\\(s\\):/ {
  for(i=1;i<=NF;i++){
    if($i ~ /CPU\\(s\\):/){
      split($i,a,":"); if(a[2] ~ /^[0-9]+$/) lscpu=a[2]
    } else if($(i-1) ~ /CPU\\(s\\):/ && $i ~ /^[0-9]+$/){ lscpu=$i }
  }
}
/^== nproc ==/ {src="nproc"; next}
src=="nproc" && /^[0-9]+$/ { nproc=$0 }
/^== \/proc\/cpuinfo ==/ {src="cpuinfo"; next}
src=="cpuinfo" && /^processor/ { cpuinfo_count++ }
/^== \/sys\/devices\/system\/cpu\/online ==/ {src="online"; next}
src=="online" && /^[0-9,-]+$/ {
  s=$0; split(s,parts,",");
  for(i=1;i<=length(parts);i++){
    if(parts[i] ~ /-/){
      split(parts[i],r,"-"); online += (r[2]-r[1]+1)
    } else if(parts[i] ~ /^[0-9]+$/) online++
  }
}
/^== \/proc\/stat ==/ {src="stat"; next}
src=="stat" && /^cpu[0-9]+/ { stat_count++ }
END{
  print "Cleaned CPU count candidates:";
  if(lscpu) print "lscpu: " lscpu;
  if(nproc) print "nproc: " nproc;
  if(cpuinfo_count) print "/proc/cpuinfo (processor entries): " cpuinfo_count;
  if(online) print "/sys/devices/system/cpu/online: " online;
  if(stat_count) print "/proc/stat (cpuN lines): " stat_count;
  print "";
  # unique numeric candidates
  delete seen;
  if(lscpu) seen[lscpu]=1;
  if(nproc) seen[nproc]=1;
  if(cpuinfo_count) seen[cpuinfo_count]=1;
  if(online) seen[online]=1;
  if(stat_count) seen[stat_count]=1;
  print "Unique candidates:";
  for(k in seen) print k;
  print "";
  # choose primary: prefer nproc, then online, then cpuinfo, then lscpu, then stat_count
  primary="";
  if(nproc) primary=nproc;
  else if(online) primary=online;
  else if(cpuinfo_count) primary=cpuinfo_count;
  else if(lscpu) primary=lscpu;
  else if(stat_count) primary=stat_count;
  print "Primary candidate (marked): " primary;
  print "";
  print "Reconciliation notes:";
  if(lscpu) print "- lscpu reported", lscpu;
  if(nproc) print "- nproc (runtime) reported", nproc;
  if(cpuinfo_count) print "- /proc/cpuinfo lists", cpuinfo_count, "processor entries (may include offline CPUs)";
  if(online) print "- /sys/devices/system/cpu/online maps to", online, "online CPUs";
  if(stat_count) print "- /proc/stat shows", stat_count, "cpuN lines (excluding aggregate)";
  print "- Primary chosen as runtime-visible (nproc) where available; if not, prefer online map then cpuinfo entries.";
}' temp_cpu_check/raw_cpu_info.txt > temp_cpu_check/cpu_count_candidates.txt
```

